public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a 2D array to represent the n-teresting space
    int[][] map = new int[n][n];

    // Initialize the map with the given paths
    for (int i = 0; i < paths.length; i++) {
        int from = paths[i][0];
        int to = paths[i][1];
        map[from][to] = 1;
    }

    // Use DFS to search for a path between the starting and ending n-tersection
    boolean[] visited = new boolean[n];
    Stack<Integer> stack = new Stack<>();
    stack.push(start[0]);
    visited[start[0]] = true;

    while (!stack.isEmpty()) {
        int current = stack.pop();
        for (int i = 0; i < n; i++) {
            if (map[current][i] == 1 && !visited[i]) {
                visited[i] = true;
                stack.push(i);
            }
        }
    }

    // Check if the ending n-tersection is visited
    for (int i = 0; i < n; i++) {
        if (visited[i] && i == end[0]) {
            return "can be travelled";
        }
    }

    return "cannot be travelled";
}

